import fitz, numpy as np
d = fitz.open('eprint/fig2.pdf')
p = d[0]
draws = p.get_drawings()
for dr in draws:
    if dr.get('width')==3.0 and str(dr.get('color'))=='(0.0, 0.0, 0.0)':
        pts=[]
        for it in dr['items']:
            if it[0]=='l':
                pts.append((it[1].x,it[1].y)); pts.append((it[2].x,it[2].y))
            elif it[0]=='c':
                for q in it[1:]:
                    pts.append((q.x,q.y))
        # dedupe consecutive
        out=[pts[0]]
        for q in pts[1:]:
            if abs(q[0]-out[-1][0])>1e-6 or abs(q[1]-out[-1][1])>1e-6:
                out.append(q)
        pts=np.array(out)
        x0,dx = 111.05, 378.55   # 10^0 MeV, per decade
        y0,dy = 393.2, 393.2-177.75  # 10^-10, per decade (upward)
        m = 10**((pts[:,0]-x0)/dx)   # MeV
        g = 10**(-10 + (y0-pts[:,1])/dy)
        print(len(m))
        for mm,gg in zip(m,g):
            print(f"{mm:.4g} {gg:.4g}")
